    data = sys.stdin.read().split()
    n, q, p = int(data[0]), int(data[1]), int(data[2])
    for k in range(q):
        l = int(data[3 + 2 * k]); r = int(data[4 + 2 * k])
        if l <= p < r:
            p += 1
        elif p == r:
            p = l
    print(p)

